405	func (m *failoverMonitor) monitorLoop(shouldQuiesce <-chan struct{}) {
406		ticker := m.opts.timeSource.newTicker(m.opts.UnhealthySamplingInterval)
407		if m.opts.monitorIterationForTesting != nil {
408			m.opts.monitorIterationForTesting <- struct{}{}
409		}
410		tickerCh := ticker.ch()
411		dirIndex := primaryDirIndex
412		var lastWriter lastWriterInfo
413		for {
414			select {
415			case <-shouldQuiesce:
416				ticker.stop()
417				m.prober.stop()
418				return
419			case <-tickerCh:
420				writerOngoingLatency, writerErr := func() (time.Duration, error) {
421					m.mu.Lock()
422					defer m.mu.Unlock()
423					if m.mu.writer != lastWriter.writer {
424						lastWriter = lastWriterInfo{writer: m.mu.writer}
425					}
426					if lastWriter.writer == nil {
427						return 0, nil
428					}
429					return lastWriter.writer.ongoingLatencyOrErrorForCurDir()
430				}()
431				switchDir := false
432				// Arbitrary value.
433				const highSecondaryErrorCountThreshold = 2
434				// We don't consider a switch if currently using the primary dir and the
435				// secondary dir has high enough errors. It is more likely that someone
436				// has misconfigured a secondary e.g. wrong permissions or not enough
437				// disk space. We only remember the error history in the context of the
438				// lastWriter since an operator can fix the underlying misconfiguration.
439				unhealthyThreshold, failoverEnabled := m.opts.UnhealthyOperationLatencyThreshold()
440	
441				if !(lastWriter.errorCounts[secondaryDirIndex] >= highSecondaryErrorCountThreshold &&
442					dirIndex == primaryDirIndex) && failoverEnabled {
443					// Switching heuristics. Subject to change based on real world experience.
444					if writerErr != nil {
445						// An error causes an immediate switch, since a LogWriter with an
446						// error is useless.
447						lastWriter.errorCounts[dirIndex]++
448						switchDir = true
449					} else if writerOngoingLatency > unhealthyThreshold {
450						// Arbitrary value.
451						const switchImmediatelyCountThreshold = 2
452						// High latency. Switch immediately if the number of switches that
453						// have been done is below the threshold, since that gives us an
454						// observation of both dirs. Once above that threshold, decay the
455						// switch rate by increasing the observed latency needed for a
456						// switch.
457						if lastWriter.numSwitches < switchImmediatelyCountThreshold ||
458							writerOngoingLatency > 2*lastWriter.ongoingLatencyAtSwitch {
459							switchDir = true
460							lastWriter.ongoingLatencyAtSwitch = writerOngoingLatency
461						}
462						// Else high latency, but not high enough yet to motivate switch.
463					} else if dirIndex == secondaryDirIndex {
464						// The writer looks healthy. We can still switch if the writer is using the
465						// secondary dir and the primary is healthy again.
466						primaryMean, primaryMax := m.prober.getMeanMax(m.opts.HealthyInterval)
467						if primaryMean < m.opts.HealthyProbeLatencyThreshold &&
468							primaryMax < m.opts.HealthyProbeLatencyThreshold {
469							switchDir = true
470						}
471					}
472				}
473				if switchDir {
474					lastWriter.numSwitches++
475					if dirIndex == secondaryDirIndex {
476						// Switching back to primary, so don't need to probe to see if
477						// primary is healthy.
478						m.prober.disableProbing()
479						dirIndex = primaryDirIndex
480					} else {
481						m.prober.enableProbing()
482						dirIndex = secondaryDirIndex
483					}
484					dir := m.opts.dirs[dirIndex]
485					m.mu.Lock()
486					now := m.opts.timeSource.now()
487					m.accumulateDurationLocked(now)
488					m.mu.dirIndex = dirIndex
489					m.mu.dirSwitchCount++
490					if dirIndex == primaryDirIndex {
491						m.mu.lastFailBackTime = now
492					}
493					if m.mu.writer != nil {
494						_ = m.mu.writer.switchToNewDir(dir)
495					}
496					m.mu.Unlock()
497				}
498			}
499			if m.opts.monitorStateForTesting != nil {
500				m.opts.monitorStateForTesting(lastWriter.numSwitches, lastWriter.ongoingLatencyAtSwitch)
501			}
502			if m.opts.monitorIterationForTesting != nil {
503				m.opts.monitorIterationForTesting <- struct{}{}
504			}
505		}
